INSERT INTO social_and_env_grieviancemonitoringlog (case_no, sex, date_claim_recieved, name_of_person_receiving_complaint, how_complaint_was_received, name_of_complainant, tell_no, complaint_content, was_recieved_of_complaint_ack, expected_decision_date, was_decison_communicated_to_complainant, communication_method, was_complainant_satisfied_with_decision, brief_note_for_NO_answer, any_follow_up_action, date_created, decision_outcome_id, loginUser_id, project_id, type_of_investment_id) VALUES ('GR-TL026', 'M', '2022-06-13', 'Baboucarr Corr', 'Letter', 'Ousman Gaye', '6754574/9754574', 'Mr. Gaye in his letter complained that the amount he is being offered does not represent the current market value of land in the area and was too low', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-03-13 14:00:45.8861190 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL027', 'M', '2022-05-29', 'Baboucarr Corr', 'In Person', 'Ebrima Barrow of Jambur', '3846873', 'Mr. Barrow complained that the D233.040 he was being compensation for his land will not be enough to get him a land of that size around Jambur and that his land has a one-meter fence on all sides', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-03-13 14:00:14.9656990 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL028', 'F', '2022-05-20', 'Baboucarr Corr', 'mail', 'Ousainatou and Assanatou Touray C/O Yahya Touray of Jabang', 'NA', 'Mr. Touray on behalf of her sister argued that the amount D528,673 being offered to her sister for a fenced and gated plot of land measuring 30X30 was not reasonable', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-03-13 13:59:28.5654970 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL029', 'M', '2022-06-20', 'Baboucarr Corr', 'Letter', 'Ebrima Kah C/O Amadou Kah', '7774686/3634680', 'In a letter of complaint Mr. Kah Claimed that he has built a big structure in his plot on land measuring 40X60X50X40 which he is going to lose to the project. He argued that the land and structure will cost about D3.5million in today market value. Pictures of the building were also presented.', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-03-13 13:58:49.3815300 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL030', 'M', '2022-06-10', 'Baboucarr Corr', 'Letter', 'Edward Kamara C/O Kujay Ceesay', '7831374', 'In the letter sent to the PIU Edward argued that he bought the said land for D285,000 and he is being offered compensation of D186,420 about D100,000 less that what he got his land for. He suggested that a compensation of D250,000 will be enough and satisfactory to him given that the project is for national development.', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-03-13 13:58:09.0458080 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL031', 'F', '2022-05-20', 'Baboucarr Corr', 'mail', 'Mamie Jallow C/O Haddy M.O Faal / Fatou', '3149374/9969936', 'Mamie in her email claimed that she is being offered a compensation of D3,078,680 for a storey building she build for about 6,500,000 over 5 years and the cost of land given that appreciation of prices the said compensation is far below her expectation', 'Y', '2022-06-30', 'Y', 'Call', 'Y', 'Not applicable', 'Closed.', '2025-03-13 13:57:29.5942230 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL032', 'M', '2022-05-20', 'Baboucarr Corr', 'Letter', 'Alieu T. Dibba', '7911774/3189646', 'Alieu claimed that his land of 20X25 will be impacted by 9X25, and the amount being offered for compensation was too low and he will instead want to be offered land compensation for the property', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Open', '2025-03-13 13:55:20.6827120 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL033', 'M', '2022-06-05', 'Baboucarr Corr', 'Letter', 'Lamin Njie C/O Basiru Njie', '7831374', 'Lamin claimed that he is being proposed a compensation amount 215,635 which was less the amount he acquired his land for in April 2014 (D350,000). He suggested that he will accept D500,000 as a reasonable compensation amount', 'Y', '2022-06-30', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-03-13 13:54:52.9553590 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL034', 'M', '2022-06-05', 'Baboucarr Corr', 'Letter', 'Omar Njie C/O Basiru Njie', '3010733/2010100', 'Omar claimed that he is being offered proposed a compensation amount that is less that he and his brother (Lamin) acquired their land for and that D500,000 will represent a fair compensation to his too.', 'Y', '2022-06-30', 'Y', 'Call', 'Y', 'Not applicable', 'Closed.', '2025-03-13 13:54:26.8393640 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL035', 'M', '2021-05-17', 'Baboucarr Corr', 'Letter', 'Yunusa Faye', '3959447 / 64994', 'A review by Baboucarr Corr for the GRC found some of Mr. Faye claim’s to be unjustifiable following a closer look at material in his claim letter', 'Y', '2022-01-03', 'Y', 'Call', 'Y', 'Not applicable', 'Closed', '2025-03-13 13:22:52.0958980 ', 20009, 19, 'D309& D6530 -GM', 'GERMP T&D');